def gen(rng):
    def fmt(ws):
        return str(len(ws)) + '\n' + '\n'.join(ws)
    tests = [
        fmt(['hello']), fmt(['a', 'a']), fmt(['Cat', 'cat', 'Cat']), fmt(['x'] * 5),
        fmt(['apple', 'banana', 'apple', 'cherry', 'banana', 'apple']),
        fmt(['a', 'b', 'c', 'd']), fmt(['A1', 'a1', 'A1', '1A', 'a1']),
    ]
    alpha = 'abcAB12'
    for _ in range(40):
        n = rng.randint(1, 25)
        pool = [''.join(rng.choice(alpha) for _ in range(rng.randint(1, 3))) for _ in range(rng.randint(1, 10))]
        tests.append(fmt([rng.choice(pool) for _ in range(n)]))
    N = 100000
    def word():
        return ''.join(rng.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(rng.randint(10, 20)))
    distinct = [word() for _ in range(N)]
    tests.append(fmt(distinct))
    pool = [word() for _ in range(50000)]
    tests.append(fmt([rng.choice(pool) for _ in range(N)]))
    tests.append(fmt(['same'] * N))
    tests.append(fmt([str(i) for i in range(N // 2)] + [str(i) for i in range(N // 2)]))
    return tests
